143	type apiKeyTransport struct {
144		// Key is the API Key to set on requests.
145		Key string
146		// Transport is the underlying HTTP transport.
147		// If nil, http.DefaultTransport is used.
148		Transport http.RoundTripper
149	}
150	
151	func (t *apiKeyTransport) RoundTrip(req *http.Request) (*http.Response, error) {
152		newReq := *req
153		args := newReq.URL.Query()
154		args.Set("key", t.Key)
155		newReq.URL.RawQuery = args.Encode()
156		return t.Transport.RoundTrip(&newReq)
157	}
158	
159	type headerTransport struct {
160		headers http.Header
161		base    http.RoundTripper
162	}
163	
164	func (t *headerTransport) RoundTrip(req *http.Request) (*http.Response, error) {
165		rt := t.base
166		newReq := *req
167		newReq.Header = make(http.Header)
168		for k, vv := range req.Header {
169			newReq.Header[k] = vv
170		}
171	
172		for k, v := range t.headers {
173			newReq.Header[k] = v
174		}
175	
176		return rt.RoundTrip(&newReq)
177	}
178	
179	func addOpenTelemetryTransport(trans http.RoundTripper, opts *Options) http.RoundTripper {
180		if opts.DisableTelemetry {
181			return trans
182		}
183		if gax.IsFeatureEnabled("METRICS") || gax.IsFeatureEnabled("TRACING") {
184			trans = &otelAttributeTransport{base: trans}
185		}
186		if !gax.IsFeatureEnabled("TRACING") {
187			return otelhttp.NewTransport(trans)
188		}
189		var staticAttrs []attribute.KeyValue
190		if opts.InternalOptions != nil {
191			staticAttrs = transport.StaticTelemetryAttributes(opts.InternalOptions.TelemetryAttributes)
192		}
193		otelOpts := []otelhttp.Option{
194			otelhttp.WithSpanOptions(trace.WithAttributes(staticAttrs...)),
195		}
196		return otelhttp.NewTransport(trans, otelOpts...)
197	}
