199	// otelAttributeTransport is a wrapper around an http.RoundTripper that adds
200	// custom Google Cloud-specific attributes to OpenTelemetry spans.
201	type otelAttributeTransport struct {
202		base http.RoundTripper
203	}
204	
205	// RoundTrip intercepts the HTTP request and response to enrich the active
206	// OpenTelemetry span with static and dynamic attributes, as well as detailed
207	// error information.
208	func (t *otelAttributeTransport) RoundTrip(req *http.Request) (*http.Response, error) {
209		var span trace.Span
210		if gax.IsFeatureEnabled("TRACING") {
