31	func TestAddAuthorizationMiddleware(t *testing.T) {
32		creds := auth.NewCredentials(&auth.CredentialsOptions{
33			TokenProvider: staticTP("fakeToken"),
34		})
35		tests := []struct {
36			name    string
37			client  *http.Client
38			creds   *auth.Credentials
39			wantErr bool
40			want    string
41		}{
42			{
43				name:    "missing both required fields",
44				wantErr: true,
45			},
46			{
47				name:    "missing client field",
48				creds:   creds,
49				wantErr: true,
50			},
51			{
52				name:    "missing creds field",
53				client:  internal.DefaultClient(),
54				wantErr: true,
55			},
56			{
57				name:   "works",
58				client: internal.DefaultClient(),
59				creds:  creds,
60				want:   "fakeToken",
61			},
62			{
63				name:   "works, no transport",
64				client: &http.Client{},
65				creds:  creds,
66				want:   "fakeToken",
67			},
68		}
69		for _, tt := range tests {
70			t.Run(tt.name, func(t *testing.T) {
71				err := AddAuthorizationMiddleware(tt.client, tt.creds)
72				if tt.wantErr && err == nil {
73					t.Fatalf("AddAuthorizationMiddleware() = nil, want error")
74				}
75				if tt.wantErr {
76					return
77				}
78				ts := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
79					got := r.Header.Get("Authorization")
80					if !strings.Contains(got, tt.want) {
81						t.Errorf("got %q, want contain %q", got, tt.want)
82					}
83	
84				}))
85				defer ts.Close()
86				tt.client.Get(ts.URL)
87			})
88		}
89	}
