91	func TestAddAuthorizationMiddleware_HandlesNonTransportAsDefaultTransport(t *testing.T) {
92		client := &http.Client{}
93		creds := auth.NewCredentials(&auth.CredentialsOptions{
94			TokenProvider: staticTP("fakeToken"),
95		})
96		dt := http.DefaultTransport
97	
98		http.DefaultTransport = &rt{}
99		defer func() { http.DefaultTransport = dt }()
100	
101		err := AddAuthorizationMiddleware(client, creds)
102		if err != nil {
103			t.Fatal(err)
104		}
105	
106		at := client.Transport.(*authTransport)
107		_, ok := at.base.(*rt)
108		if !ok {
109			t.Errorf("got %T, want %T", at.base, &rt{})
110		}
111	}
