type scratchRT struct {
	resp *http.Response
	err  error
}

func (r *scratchRT) RoundTrip(req *http.Request) (*http.Response, error) {
	if r.resp != nil {
		r.resp.Request = req
	}
	return r.resp, r.err
}

func mkResp(status int, body string, contentLength int64) *http.Response {
	return &http.Response{
		StatusCode:    status,
		Status:        http.StatusText(status),
		Body:          io.NopCloser(strings.NewReader(body)),
		ContentLength: contentLength,
		Header:        make(http.Header),
	}
}

func runScratch(t *testing.T, base http.RoundTripper, ctx context.Context, readBody bool) map[string]any {
	t.Helper()
	var buf bytes.Buffer
	logger := slog.New(slog.NewJSONHandler(&buf, &slog.HandlerOptions{Level: slog.LevelDebug}))
	tr := &otelAttributeTransport{base: base, logger: logger}
	req, _ := http.NewRequestWithContext(ctx, "GET", "http://example.com/foo", nil)
	resp, err := tr.RoundTrip(req)
	if resp != nil && resp.Body != nil {
		if readBody {
			io.ReadAll(resp.Body)
		}
		resp.Body.Close()
	}
	_ = err
	out := strings.TrimSpace(buf.String())
	if out == "" {
		return nil
	}
	if strings.Count(out, "\n") > 0 {
		t.Fatalf("expected exactly one record, got:\n%s", out)
	}
	var m map[string]any
	if e := json.Unmarshal([]byte(out), &m); e != nil {
		t.Fatalf("bad json: %v (%s)", e, out)
	}
	delete(m, "time")
	return m
}

func TestScratch(t *testing.T) {
	gax.TestOnlyResetIsFeatureEnabled()
	defer gax.TestOnlyResetIsFeatureEnabled()
	t.Setenv("GOOGLE_SDK_GO_EXPERIMENTAL_LOGGING", "true")
	gax.TestOnlyResetIsFeatureEnabled()

	body := `{"error":{"code":429,"message":"rate limit hit","status":"RESOURCE_EXHAUSTED","details":[{"@type":"type.googleapis.com/google.rpc.ErrorInfo","reason":"RATE_LIMIT_EXCEEDED","domain":"googleapis.com","metadata":{"quota_limit":"100"}}]}}`
	got := runScratch(t, &scratchRT{resp: mkResp(429, body, int64(len(body)))}, context.Background(), true)
	t.Logf("actionable: %#v", got)
	if got["error.type"] != "RATE_LIMIT_EXCEEDED" || got["msg"] != "rate limit hit" || got["rpc.response.status_code"] != "RESOURCE_EXHAUSTED" || got["rpc.system.name"] != "http" || got["gcp.errors.domain"] != "googleapis.com" || got["gcp.errors.metadata.quota_limit"] != "100" || got["level"] != "DEBUG" {
		t.Errorf("actionable mismatch: %#v", got)
	}
	if got["http.response.status_code"] != float64(429) || got["http.request.method"] != "GET" {
		t.Errorf("http fields mismatch: %#v", got)
	}

	// ContentLength > 8192 => immediate, status string msg, no wrap.
	big := strings.Repeat("x", 9000)
	got = runScratch(t, &scratchRT{resp: mkResp(400, big, 9000)}, context.Background(), false)
	t.Logf("bigCL: %#v", got)
	if got["msg"] != "Bad Request" {
		t.Errorf("bigCL msg mismatch: %#v", got)
	}

	// Actual content > 8192, ContentLength unknown => fallback status string.
	got = runScratch(t, &scratchRT{resp: mkResp(400, big, -1)}, context.Background(), true)
	t.Logf("bigChunked: %#v", got)
	if got["msg"] != "Bad Request" {
		t.Errorf("bigChunked msg mismatch: %#v", got)
	}

	// resend_count + resource_name from context.
	ctx := callctx.WithTelemetryContext(context.Background(), "resend_count", "2")
	ctx = callctx.WithTelemetryContext(ctx, "resource_name", "my-resource")
	got = runScratch(t, &scratchRT{resp: mkResp(429, body, int64(len(body)))}, ctx, true)
	t.Logf("ctx: %#v", got)
	if got["http.request.resend_count"] != float64(2) || got["gcp.resource.destination.id"] != "my-resource" {
		t.Errorf("ctx fields mismatch: %#v", got)
	}

	// Transport error: deadline exceeded.
	got = runScratch(t, &scratchRT{err: context.DeadlineExceeded}, context.Background(), false)
	t.Logf("deadline: %#v", got)
	if got["error.type"] != "CLIENT_TIMEOUT" || got["rpc.response.status_code"] != "DEADLINE_EXCEEDED" {
		t.Errorf("deadline mismatch: %#v", got)
