	if got["error.type"] != "CLIENT_CANCELLED" || got["rpc.response.status_code"] != "CANCELED" {
		t.Errorf("cancel mismatch: %#v", got)
	}

	// Transport error: other.
	got = runScratch(t, &scratchRT{err: io.ErrUnexpectedEOF}, context.Background(), false)
	t.Logf("other: %#v", got)
	if got["rpc.response.status_code"] != "UNKNOWN" {
		t.Errorf("other mismatch: %#v", got)
	}

	// Early close (no read): still emits.
	got = runScratch(t, &scratchRT{resp: mkResp(500, `{"error":{"message":"boom"}}`, int64(28))}, context.Background(), false)
	t.Logf("earlyclose: %#v", got)
	if got == nil {
		t.Errorf("early close should still emit")
	}

	// Disabled logging => no output.
