243	// logHTTPError emits a single DEBUG-level structured log record describing an
244	// HTTP error.
245	func logHTTPError(ctx context.Context, logger *slog.Logger, r logRecord) {
246		grpcStatus := r.grpcStatus
247		if grpcStatus == "" {
248			grpcStatus = httpStatusToGRPCString(r.statusCode)
249		}
250		attrs := []slog.Attr{
251			slog.String("rpc.system.name", "http"),
252			slog.String("rpc.response.status_code", grpcStatus),
253		}
254		// Only include the numeric HTTP status when there was an actual response.
255		if r.statusCode > 0 {
256			attrs = append(attrs, slog.Int("http.response.status_code", r.statusCode))
257		}
258		if r.method != "" {
259			attrs = append(attrs, slog.String("http.request.method", r.method))
260		}
261		if resendCountStr, ok := callctx.TelemetryFromContext(ctx, "resend_count"); ok {
262			if count, e := strconv.Atoi(resendCountStr); e == nil {
263				attrs = append(attrs, slog.Int("http.request.resend_count", count))
264			}
265		}
266		if resName, ok := callctx.TelemetryFromContext(ctx, "resource_name"); ok {
267			attrs = append(attrs, slog.String("gcp.resource.destination.id", resName))
268		}
269		if r.domain != "" {
270			attrs = append(attrs, slog.String("gcp.errors.domain", r.domain))
271		}
272		for k, v := range r.metadata {
273			attrs = append(attrs, slog.String("gcp.errors.metadata."+k, v))
274		}
275		attrs = append(attrs, slog.String("error.type", r.errorType))
276	
277		logger.LogAttrs(ctx, slog.LevelDebug, r.msg, attrs...)
