280	// transportErrorInfo maps a transport-level error (i.e. one where no HTTP
281	// response was received) to a gRPC-style status string and an error type.
282	func transportErrorInfo(err error) (errorType, statusCode string) {
283		switch {
284		case errors.Is(err, context.DeadlineExceeded):
285			return "CLIENT_TIMEOUT", "DEADLINE_EXCEEDED"
286		case errors.Is(err, context.Canceled):
