295	func httpStatusToGRPCString(code int) string {
296		switch code {
297		case http.StatusBadRequest:
298			return "INVALID_ARGUMENT"
299		case http.StatusUnauthorized:
300			return "UNAUTHENTICATED"
301		case http.StatusForbidden:
302			return "PERMISSION_DENIED"
303		case http.StatusNotFound:
304			return "NOT_FOUND"
305		case http.StatusConflict:
306			return "ABORTED"
307		case http.StatusRequestedRangeNotSatisfiable:
308			return "OUT_OF_RANGE"
309		case http.StatusTooManyRequests:
310			return "RESOURCE_EXHAUSTED"
311		case 499:
312			return "CANCELED"
313		case http.StatusInternalServerError:
314			return "INTERNAL"
315		case http.StatusNotImplemented:
316			return "UNIMPLEMENTED"
317		case http.StatusServiceUnavailable:
318			return "UNAVAILABLE"
319		case http.StatusGatewayTimeout:
320			return "DEADLINE_EXCEEDED"
321		}
322		switch {
323		case code >= 200 && code < 300:
324			return "OK"
325		case code >= 400 && code < 500:
326			return "FAILED_PRECONDITION"
327		case code >= 500 && code < 600:
328			return "INTERNAL"
329		}
330		return "UNKNOWN"
331	}
